-- Admin > Email (Django migration 0020_email_settings of 0.4.2). A database that a
-- preview of 0.4.2 migrated has the table already, with its settings: it stays as it is.
CREATE TABLE IF NOT EXISTS "portal_emailsettings" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "portal_emailsettings_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"provider" varchar(12) NOT NULL,
	"from_address" varchar(254) NOT NULL,
	"reply_to_address" varchar(254) NOT NULL,
	"mailersend_token_sealed" text NOT NULL,
	"webhook_secret_sealed" text NOT NULL,
	"smtp_host" varchar(253) NOT NULL,
	"smtp_port" integer NOT NULL,
	"smtp_security" varchar(8) NOT NULL,
	"smtp_username" varchar(254) NOT NULL,
	"smtp_password_sealed" text NOT NULL,
	"confirmation_enabled" boolean NOT NULL,
	"confirmation_texts" jsonb NOT NULL,
	"webhook_received_at" timestamp with time zone,
	"updated_at" timestamp with time zone NOT NULL,
	CONSTRAINT "portal_emailsettings_smtp_port_check" CHECK ("portal_emailsettings"."smtp_port" >= 0)
);
--> statement-breakpoint
-- Django's record of its migration 0020, so that 0.4.2 or later never creates the table again.
DO $$
BEGIN
  IF to_regclass('public.django_migrations') IS NOT NULL THEN
    EXECUTE $insert$
      INSERT INTO django_migrations (app, name, applied)
      SELECT 'portal', '0020_email_settings', now()
      WHERE NOT EXISTS (
        SELECT 1 FROM django_migrations WHERE app = 'portal' AND name = '0020_email_settings'
      )
    $insert$;
  END IF;
END
$$;
